import pandas as pd
from genoml import utils

MPRA_UPSTREAM =   ''
MPRA_DOWNSTREAM = ''

mpra_df = pd.read_csv('data/Gosai_MPRA/Gosai_MPRA_760679.tsv', sep='\t')

mpra_df['seq'] = mpra_df['seq'].map(lambda x: utils.pad_seq(x, padded_len=600, pad_mode='given', left_pad_seq=MPRA_UPSTREAM, right_pad_seq=MPRA_DOWNSTREAM))
print(mpra_df['seq'].str.len().value_counts())

mpra_df.to_csv('data/Gosai_MPRA/Gosai_MPRA_760679_600bp.tsv', sep='\t', index=False)
